# Mover modelo para pasta: padrão presumido (atualiza o modelo com o campo da
# pasta). Se o GHL responder 404/400, capture método/URL/corpo reais no
# DevTools movendo um modelo pela interface e ajuste em
# "Pastas → Endpoints (avançado)". Fica salvo no creds.json e na sub-conta.
DEFAULT_MOVE_URL = ENDPOINT_TEMPLATE + "/{template_id}"
DEFAULT_MOVE_METHOD = "PUT"

# Quantidade máxima de modelos por lote (campo "Quantidade").
MAX_QTY = 500

DEFAULT_EXTRA_HEADERS = {
    "channel": "APP",
    "source": "WEB_USER",
    "version": "2021-07-28",
    "x-translations-lang": "pt-BR",
    "app-name": "spm-ts",
}

