@app.route("/api/plan", methods=["POST"])
def api_plan():
    """Descobre quais índices (v1, v2, v3...) já existem na sub-conta e
    devolve os próximos 'qty' índices livres, pulando os ocupados."""
    data = request.get_json(force=True)

    creds = {
        "location_id": data.get("location_id", ""),
        "auth_mode": data.get("auth_mode", "session"),
        "pit_token": data.get("pit_token", ""),
        "auth_token": data.get("auth_token", ""),
        "token_id": data.get("token_id", ""),
    }
    save_creds(creds)

    base_name = sanitize_name_part(data.get("base_name", ""))
    date_suffix = sanitize_name_part(data.get("date_suffix", ""))
    try:
        qty = max(1, min(int(data.get("qty", 1)), MAX_QTY))
    except (TypeError, ValueError):
        qty = 1

    existing = list_existing_template_names(creds)
    if existing is None:
        # não deu pra consultar os modelos existentes -- segue sequencial 1..qty
        return jsonify({
            "indices": list(range(1, qty + 1)),
            "skipped": [],
            "warning": "Não foi possível consultar os modelos já existentes; "
                       "usando sequência padrão a partir de v1.",
        })

    indices = next_available_indices(existing, base_name, date_suffix, qty)
    already_taken = [
        i for i in range(1, (max(indices) if indices else qty) + 1)
        if i not in indices
    ]
    return jsonify({"indices": indices, "skipped": already_taken, "warning": ""})


