@app.route("/api/test-connection", methods=["POST"])
def api_test_connection():
    """Faz uma leitura simples (lista de modelos) só pra ver se o token responde."""
    data = request.get_json(force=True)
    creds = creds_from_request(data)

    if not creds["location_id"].strip():
        return jsonify({"ok": False, "status": 0, "msg": "Preencha o Location ID."})
    if creds["auth_mode"] == "pit":
        if not creds["pit_token"].strip():
            return jsonify({"ok": False, "status": 0, "msg": "Cole o Private Integration Token."})
    elif not creds["auth_token"].strip() or not creds["token_id"].strip():
        return jsonify({"ok": False, "status": 0, "msg": "Cole o Authorization e o token-id."})

    save_creds(creds)
    url = ENDPOINT_TEMPLATE.format(location_id=creds["location_id"].strip())
    started = time.time()
    try:
        res = requests.get(url, headers=build_auth_headers(creds), timeout=15)
    except Exception as e:
        return jsonify({"ok": False, "status": 0, "msg": f"Sem conexão com o GHL: {e}"})
    ms = int((time.time() - started) * 1000)

    if res.ok:
        count = None
        try:
            body = res.json()
            if isinstance(body, list):
                count = len(body)
            elif isinstance(body, dict):
                items = (body.get("templates") or body.get("data") or body.get("whatsappTemplates")
                         or body.get("whatsAppTemplates") or [])
                count = len(items) if isinstance(items, list) else None
        except ValueError:
            pass
        extra = f"{count} modelos na sub-conta, " if count is not None else ""
        return jsonify({"ok": True, "status": res.status_code,
                        "msg": f"Conexão OK — token funcionando ({extra}{ms} ms)"})

    messages = {
        401: "Token expirado ou inválido (HTTP 401) — recapture no DevTools.",
        403: "Acesso negado (HTTP 403) — o token não tem permissão nessa sub-conta ou o Location ID é de outra conta.",
        404: "Não encontrado (HTTP 404) — confira o Location ID.",
    }
    msg = messages.get(res.status_code, f"O GHL respondeu HTTP {res.status_code}: {res.text[:200]}")
    return jsonify({"ok": False, "status": res.status_code, "msg": msg, "expired": res.status_code == 401})


# ---------- Pastas ----------

def creds_from_request(data):
    return {
        "location_id": data.get("location_id", ""),
        "auth_mode": data.get("auth_mode", "session"),
        "pit_token": data.get("pit_token", ""),
        "auth_token": data.get("auth_token", ""),
        "token_id": data.get("token_id", ""),
    }


def folder_config_from_request(data):
    """Lê a config de endpoints de pasta e salva junto com as credenciais."""
    cfg = {
        "folder_create_url": (data.get("folder_create_url") or DEFAULT_FOLDER_ENDPOINT).strip(),
        "folder_list_url": (data.get("folder_list_url") or DEFAULT_FOLDER_ENDPOINT).strip(),
        "folder_delete_url": (data.get("folder_delete_url") or DEFAULT_FOLDER_ENDPOINT).strip(),
        "folder_name_key": (data.get("folder_name_key") or "name").strip(),
        "template_folder_key": (data.get("template_folder_key") or "folderId").strip(),
        "move_url": (data.get("move_url") or DEFAULT_MOVE_URL).strip(),
        "move_method": normalize_move_method(data.get("move_method")),
        "move_body": (data.get("move_body") or "").strip(),
    }
    return cfg


def normalize_move_method(method):
    method = (method or DEFAULT_MOVE_METHOD).strip().upper()
    return method if method in ("PUT", "PATCH", "POST") else DEFAULT_MOVE_METHOD


def fill_location(url, location_id):
    return url.replace("{location_id}", location_id.strip())


def find_id(obj, depth=0):
    """Procura o id da pasta na resposta, que pode vir em formatos variados."""
    if depth > 4:
        return ""
    if isinstance(obj, dict):
        for key in ("id", "_id", "folderId", "folder_id"):
            val = obj.get(key)
            if isinstance(val, (str, int)) and str(val):
                return str(val)
        for key in ("folder", "data", "result", "item"):
            if key in obj:
                found = find_id(obj[key], depth + 1)
                if found:
                    return found
    elif isinstance(obj, list) and obj:
        return find_id(obj[0], depth + 1)
    return ""


UUID_RE = re.compile(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")
IGNORED_ID_KEYS = {"locationid", "location_id", "companyid", "company_id", "userid", "user_id",
                   "createdby", "updatedby", "parentid", "parent_id", "altid", "alttype"}


def folder_id_candidates(item):
    """Lista TODOS os campos de id da pasta. O GHL costuma devolver dois ids:
    um _id interno (24 caracteres, tipo 6ab28c28fa66d2d2cd3db360) e um id em
    formato UUID (9f66d106-c164-...). O template precisa do UUID; mandar o
    _id faz o modelo cair fora da pasta sem dar erro."""
    cands = []
    for key, val in item.items():
        if not isinstance(val, (str, int)) or not str(val).strip():
            continue
        k = key.lower()
        if k in IGNORED_ID_KEYS:
            continue
        if k in ("id", "_id", "uuid") or k.endswith("id") or k.endswith("_id"):
            cands.append({"key": key, "value": str(val).strip()})
    # UUID primeiro, depois folderId/id, e _id por último
    def rank(c):
        if UUID_RE.match(c["value"]):
            return 0
        if c["key"].lower() in ("folderid", "folder_id", "id", "uuid"):
            return 1
        if c["key"] == "_id":
            return 3
        return 2
    return sorted(cands, key=rank)


def extract_folder_list(data):
    if isinstance(data, list):
        items = data
    elif isinstance(data, dict):
        items = (data.get("folders") or data.get("data") or data.get("items")
                 or data.get("result") or [])
        if isinstance(items, dict):
            items = items.get("folders") or items.get("items") or []
    else:
        items = []

    folders = []
    for it in items:
        if not isinstance(it, dict):
            continue
        cands = folder_id_candidates(it)
        name = it.get("name") or it.get("folderName") or it.get("title") or "(sem nome)"
        if cands:
            folders.append({
                "id": cands[0]["value"],
                "candidates": cands,
                "name": name,
                "raw": json.dumps(it, ensure_ascii=False, indent=2)[:1500],
            })
    return folders


@app.route("/api/create-folder", methods=["POST"])
def api_create_folder():
    data = request.get_json(force=True)
    creds = creds_from_request(data)
    cfg = folder_config_from_request(data)
    save_creds({**creds, **cfg})

    name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"ok": False, "msg": "nome vazio", "detail": ""})

    url = fill_location(cfg["folder_create_url"], creds["location_id"])
    payload = {cfg["folder_name_key"]: name}
    headers = build_auth_headers(creds)

    try:
        res = requests.post(url, headers=headers, json=payload, timeout=20)
    except Exception as e:
        return jsonify({"ok": False, "name": name, "msg": "erro de conexão", "detail": str(e)})

    if not res.ok:
        hint = ""
        if res.status_code == 404:
            hint = ("\n\nEndpoint não encontrado. Crie uma pasta pela interface do GHL com o "
                    "DevTools aberto (F12 → Network), copie a URL da requisição e cole em "
                    "'Endpoints de pasta (avançado)'.")
        elif res.status_code == 401:
            hint = "\n\nToken expirado — recapture no DevTools."
        return jsonify({"ok": False, "name": name, "msg": f"HTTP {res.status_code}",
                        "detail": res.text[:800] + hint})

    try:
        body = res.json()
    except ValueError:
        body = {}
    new_id = find_id(body)
    obj = body
    for key in ("folder", "data", "result", "item"):
        if isinstance(obj, dict) and isinstance(obj.get(key), dict):
            obj = obj[key]
            break
    if isinstance(obj, dict):
        cands = folder_id_candidates(obj)
        if cands:
            new_id = cands[0]["value"]
    return jsonify({"ok": True, "name": name, "id": new_id,
                    "msg": f"criada (HTTP {res.status_code})", "detail": ""})


def delete_one_folder(creds, cfg, folder_id, name=""):
    """Apaga uma pasta pelo id. Endpoint presumido: DELETE .../folder/{folder_id}.
    Se o GHL responder 404, capture a URL real no DevTools (apagando uma pasta
    pela interface) e ajuste em 'Pastas → Endpoints (avançado) → Apagar pasta'."""
    location_id = creds["location_id"].strip()
    base_url = fill_location(cfg["folder_delete_url"], location_id)
    url = base_url.rstrip("/") + f"/{folder_id}"
    headers = build_auth_headers(creds)

    try:
        res = requests.delete(url, headers=headers, timeout=20)
        if res.ok:
            return {"id": folder_id, "name": name, "ok": True,
                    "msg": f"apagada (HTTP {res.status_code})", "detail": ""}
        hint = ""
        if res.status_code == 404:
            hint = ("\n\nEndpoint não encontrado. Apague uma pasta pela interface do GHL "
                    "com o DevTools aberto (F12 → Network), copie a URL da requisição e "
                    "cole em 'Endpoints de pasta (avançado) → Apagar pasta'.")
        elif res.status_code == 401:
            hint = "\n\nToken expirado — recapture no DevTools."
        return {"id": folder_id, "name": name, "ok": False,
                "msg": f"HTTP {res.status_code}", "detail": res.text[:800] + hint}
    except Exception as e:
        return {"id": folder_id, "name": name, "ok": False, "msg": "erro de conexão", "detail": str(e)}


@app.route("/api/delete-folder", methods=["POST"])
def api_delete_folder():
    data = request.get_json(force=True)
    creds = creds_from_request(data)
    cfg = folder_config_from_request(data)
    save_creds({**creds, **cfg})

    folder_id = (data.get("folder_id") or data.get("id") or "").strip()
    name = (data.get("name") or "").strip()
    if not folder_id:
        return jsonify({"ok": False, "msg": "id da pasta vazio", "detail": ""})

    result = delete_one_folder(creds, cfg, folder_id, name)
    return jsonify(result)


def move_one_template(creds, cfg, template_id, name, folder_id):
    """Move um modelo para uma pasta. URL, método e corpo vêm da config
    (Pastas → Endpoints avançado), com os coringas {location_id},
    {template_id}, {template_name} e {folder_id}."""
    location_id = creds["location_id"].strip()
    name = name or ""

    url = cfg["move_url"]
    for key, val in (("{location_id}", location_id), ("{template_id}", str(template_id)),
                     ("{template_name}", name), ("{folder_id}", folder_id)):
        url = url.replace(key, quote(val, safe=""))

    if cfg["move_body"]:
        raw = cfg["move_body"]
        for key, val in (("{location_id}", location_id), ("{template_id}", str(template_id)),
                         ("{template_name}", name), ("{folder_id}", folder_id)):
            raw = raw.replace(key, json.dumps(val)[1:-1])  # escapa aspas/barras
        try:
            payload = json.loads(raw)
        except ValueError as e:
            return {"id": template_id, "name": name, "ok": False,
                    "msg": "corpo JSON inválido", "detail": f"Confira o corpo em 'Endpoints (avançado)': {e}"}
    else:
        payload = {cfg["template_folder_key"] or "folderId": folder_id}

    headers = build_auth_headers(creds)
    try:
        res = requests.request(cfg["move_method"], url, headers=headers, json=payload, timeout=20)
    except Exception as e:
        return {"id": template_id, "name": name, "ok": False, "msg": "erro de conexão", "detail": str(e)}

    if res.ok:
        msg = f"movido (HTTP {res.status_code})"
        note = ""
        if folder_id in res.text:
            msg += " · na pasta ✓"
        elif res.text.strip():
            note = ("Aviso: o GHL aceitou, mas a resposta não menciona a pasta. Clique em "
                    "'Buscar modelos existentes' pra conferir se ele entrou na pasta.")
        return {"id": template_id, "name": name, "ok": True, "msg": msg, "detail": note}

    hint = ""
    if res.status_code in (404, 405):
        hint = ("\n\nEndpoint/método não aceito. Mova um modelo pela interface do GHL com o "
                "DevTools aberto (F12 → Network), copie método, URL e corpo da requisição e "
                "cole em 'Pastas → Endpoints (avançado) → Mover modelo'.")
    elif res.status_code == 401:
        hint = "\n\nToken expirado — recapture no DevTools."
    return {"id": template_id, "name": name, "ok": False,
            "msg": f"HTTP {res.status_code}", "detail": res.text[:800] + hint}


@app.route("/api/move-template", methods=["POST"])
def api_move_template():
    data = request.get_json(force=True)
    creds = creds_from_request(data)
    cfg = folder_config_from_request(data)
    save_creds({**creds, **cfg})

    template_id = str(data.get("id") or "").strip()
    name = (data.get("name") or "").strip()
    folder_id = str(data.get("folder_id") or "").strip()
    if not template_id:
        return jsonify({"id": template_id, "name": name, "ok": False, "msg": "id do modelo ausente", "detail": ""})
    if not folder_id:
        return jsonify({"id": template_id, "name": name, "ok": False, "msg": "pasta de destino não escolhida", "detail": ""})

    return jsonify(move_one_template(creds, cfg, template_id, name, folder_id))


@app.route("/api/list-folders", methods=["POST"])
def api_list_folders():
    data = request.get_json(force=True)
    creds = creds_from_request(data)
    cfg = folder_config_from_request(data)
    save_creds({**creds, **cfg})

    url = fill_location(cfg["folder_list_url"], creds["location_id"])
    try:
        res = requests.get(url, headers=build_auth_headers(creds), timeout=20)
        if not res.ok:
            return jsonify({"ok": False, "folders": [],
                            "error": f"HTTP {res.status_code}: {res.text[:400]}"})
        folders = extract_folder_list(res.json())
    except Exception as e:
        return jsonify({"ok": False, "folders": [], "error": str(e)})
    return jsonify({"ok": True, "folders": folders})


@app.route("/api/list-subaccounts", methods=["GET"])
def api_list_subaccounts():
    subs = load_subaccounts()
    # devolve como lista ordenada por label, pra popular o <select>
    result = [{"key": k, **v} for k, v in subs.items()]
    result.sort(key=lambda s: (s.get("label") or "").lower())
    return jsonify({"ok": True, "subaccounts": result})


@app.route("/api/save-subaccount", methods=["POST"])
def api_save_subaccount():
    data = request.get_json(force=True)
    label = (data.get("label") or "").strip()
    if not label:
        return jsonify({"ok": False, "msg": "dê um nome pra sub-conta (ex: Polishop)"})

    key = subaccount_key(label)
    if not key:
        return jsonify({"ok": False, "msg": "nome inválido"})

    entry = {
        "label": label,
        "location_id": (data.get("location_id") or "").strip(),
        "folder_create_url": (data.get("folder_create_url") or DEFAULT_FOLDER_ENDPOINT).strip(),
        "folder_list_url": (data.get("folder_list_url") or DEFAULT_FOLDER_ENDPOINT).strip(),
        "folder_delete_url": (data.get("folder_delete_url") or DEFAULT_FOLDER_ENDPOINT).strip(),
        "folder_name_key": (data.get("folder_name_key") or "name").strip(),
        "template_folder_key": (data.get("template_folder_key") or "folderId").strip(),
        "move_url": (data.get("move_url") or DEFAULT_MOVE_URL).strip(),
        "move_method": normalize_move_method(data.get("move_method")),
        "move_body": (data.get("move_body") or "").strip(),
    }
    subs = load_subaccounts()
    subs[key] = entry
    save_subaccounts(subs)
    return jsonify({"ok": True, "key": key, "subaccount": entry,
                    "msg": f'sub-conta "{label}" salva'})


@app.route("/api/delete-subaccount", methods=["POST"])
def api_delete_subaccount():
    data = request.get_json(force=True)
    key = (data.get("key") or "").strip()
    if not key:
        return jsonify({"ok": False, "msg": "sub-conta não informada"})
    subs = load_subaccounts()
    if key not in subs:
        return jsonify({"ok": False, "msg": "sub-conta não encontrada"})
    label = subs[key].get("label", key)
    del subs[key]
    save_subaccounts(subs)
    return jsonify({"ok": True, "msg": f'sub-conta "{label}" apagada'})


